// ---- Utility formatters ----
const fmtNum = (n, d = 2) => {
  if (n == null || isNaN(n)) return "—";
  return Number(n).toLocaleString("en-US", {
    minimumFractionDigits: d,
    maximumFractionDigits: d,
  });
};

const fmtUSD = (n) => {
  const sign = n >= 0 ? "+" : "";
  return sign + fmtNum(n, 0);
};

const fmtVN = (n) => {
  const abs = Math.abs(n);
  const sign = n < 0 ? "-" : "";
  if (abs >= 1_000_000) return sign + (abs / 1_000_000).toFixed(2) + "M";
  if (abs >= 1_000) return sign + (abs / 1_000).toFixed(1) + "k";
  return sign + abs.toFixed(0);
};

const fmtPrice = (n) => fmtNum(n, 3);

// ============================================================
// PURE BACKTEST FUNCTION — runs the full session with given perillas
// Used by spread sweep (offline; no React state mutation)
// ============================================================
function runBacktest(p) {
  let cash = 0, inventory = 0, spreadPnL = 0;
  let fillsBuy = 0, fillsSell = 0;
  let maxInv = 0, minInv = 0;
  let lastMid = TRADES[0]?.p ?? 0;
  const midWindow = [];

  for (let i = 0; i < TRADES.length; i++) {
    const trade = TRADES[i];
    midWindow.push(trade.p);
    if (midWindow.length > MID_WINDOW) midWindow.shift();
    const mid = midWindow.reduce((a, b) => a + b, 0) / midWindow.length;

    const skewOffset = p.autoSkew && p.invCap > 0
      ? -(inventory / p.invCap) * p.skewIntensity * p.spread * 0.5
      : 0;

    const bid = mid - p.spread / 2 + skewOffset;
    const offer = mid + p.spread / 2 + skewOffset;

    if (trade.d === "B" && offer <= trade.p) {
      const wouldBeInv = inventory - p.quoteSize;
      if (wouldBeInv >= -p.invCap) {
        const fillSize = Math.min(p.quoteSize, trade.s);
        inventory -= fillSize;
        cash += offer * fillSize;
        spreadPnL += (offer - mid) * fillSize;
        fillsSell++;
      }
    } else if (trade.d === "S" && bid >= trade.p) {
      const wouldBeInv = inventory + p.quoteSize;
      if (wouldBeInv <= p.invCap) {
        const fillSize = Math.min(p.quoteSize, trade.s);
        inventory += fillSize;
        cash -= bid * fillSize;
        spreadPnL += (mid - bid) * fillSize;
        fillsBuy++;
      }
    }

    if (inventory > maxInv) maxInv = inventory;
    if (inventory < minInv) minInv = inventory;
    lastMid = mid;
  }

  const totalPnL = cash + inventory * lastMid;
  return {
    spread: p.spread,
    totalPnL,
    spreadPnL,
    invPnL: totalPnL - spreadPnL,
    totalFills: fillsBuy + fillsSell,
    fillsBuy,
    fillsSell,
    maxInv,
    minInv,
    finalInv: inventory,
  };
}

const SWEEP_SPREADS = [0.04, 0.05, 0.06, 0.08, 0.10, 0.12, 0.15, 0.18, 0.22, 0.27, 0.32, 0.40];

// ============================================================
// MAIN COMPONENT
// ============================================================
export default function MMWorkstation() {
  // ---- Perillas (user-controlled) ----
  const [spread, setSpread] = useState(0.10);          // in price units (USD cents)
  const [quoteSize, setQuoteSize] = useState(20000);   // VN per side
  const [skewIntensity, setSkewIntensity] = useState(1.0);
  const [autoSkew, setAutoSkew] = useState(true);
  const [invCap, setInvCap] = useState(150000);

  // ---- Replay control ----
  const [isPlaying, setIsPlaying] = useState(false);
  const [speed, setSpeed] = useState(60);

  // ---- Display state (re-renders UI) ----
  const initMid = TRADES[0]?.p ?? 63;
  const [display, setDisplay] = useState({
    index: 0,
    ts: TRADES[0]?.ts ?? "—",
    mid: initMid,
    bid: initMid - 0.05,
    offer: initMid + 0.05,
    inventory: 0,
    spreadPnL: 0,
    invPnL: 0,
    totalPnL: 0,
    fillsBuy: 0,
    fillsSell: 0,
    volTraded: 0,
    fills: [],
    history: [],
    invSeries: [],
    toxScore: 0,
    toxEvalsCount: 0,
  });

  // ---- Sweep results ----
  const [sweepResults, setSweepResults] = useState(null);
  const [sweepRunning, setSweepRunning] = useState(false);

  // ---- Sim state in refs (mutated each tick) ----
  const sim = useRef(null);
  const perillas = useRef({});

  // Mirror perillas to ref so the running interval reads latest values
  perillas.current = { spread, quoteSize, skewIntensity, autoSkew, invCap };

  const initSim = () => ({
    index: 0,
    cash: 0,
    inventory: 0,
    spreadPnL: 0,
    midWindow: [],
    fills: [],
    fillsBuy: 0,
    fillsSell: 0,
    volTraded: 0,
    history: [],
    lastQuote: { mid: TRADES[0]?.p ?? 0, bid: 0, offer: 0 },
    // Tox tracking
    pendingFills: [],   // fills not yet evaluated (need lookahead)
    closedEvals: [],    // drift evaluations (signed: + adverse, - favorable)
    invSeries: [],      // sparkline data for inventory over time
  });

  if (sim.current === null) sim.current = initSim();

  // ---- Reset ----
  const reset = useCallback(() => {
    sim.current = initSim();
    setIsPlaying(false);
    const m = TRADES[0]?.p ?? 63;
    setDisplay({
      index: 0,
      ts: TRADES[0]?.ts ?? "—",
      mid: m,
      bid: m - 0.05,
      offer: m + 0.05,
      inventory: 0, spreadPnL: 0, invPnL: 0, totalPnL: 0,
      fillsBuy: 0, fillsSell: 0, volTraded: 0,
      fills: [], history: [],
      invSeries: [], toxScore: 0, toxEvalsCount: 0,
    });
  }, []);

  // ---- Spread sweep ----
  const runSweep = useCallback(() => {
    setSweepRunning(true);
    setIsPlaying(false);
    // Defer to next frame so the spinner can show
    setTimeout(() => {
      const basePerillas = {
        quoteSize, skewIntensity, autoSkew, invCap,
      };
      const results = SWEEP_SPREADS.map(s =>
        runBacktest({ ...basePerillas, spread: s })
      );
      setSweepResults(results);
      setSweepRunning(false);
    }, 50);
  }, [quoteSize, skewIntensity, autoSkew, invCap]);

  // ---- Process one trade through the simulator ----
  const processTrade = (trade, p) => {
    const s = sim.current;

    // Rolling SMA for mid
    s.midWindow.push(trade.p);
    if (s.midWindow.length > MID_WINDOW) s.midWindow.shift();
    const mid = s.midWindow.reduce((a, b) => a + b, 0) / s.midWindow.length;

    // Skew offset (negative when long → push quotes down)
    const skewOffset = p.autoSkew && p.invCap > 0
      ? -(s.inventory / p.invCap) * p.skewIntensity * p.spread * 0.5
      : 0;

    const bid = mid - p.spread / 2 + skewOffset;
    const offer = mid + p.spread / 2 + skewOffset;

    // Determine fill against the real trade
    let fill = null;

    if (trade.d === "B" && offer <= trade.p) {
      // Real BUY would have hit our offer → we sell at our offer
      const wouldBeInv = s.inventory - p.quoteSize;
      if (wouldBeInv >= -p.invCap) {
        const fillSize = Math.min(p.quoteSize, trade.s);
        fill = { side: "S", price: offer, size: fillSize, ts: trade.ts, mid };
        s.inventory -= fillSize;
        s.cash += offer * fillSize;
        s.spreadPnL += (offer - mid) * fillSize;
        s.fillsSell++;
        s.volTraded += fillSize;
      }
    } else if (trade.d === "S" && bid >= trade.p) {
      // Real SELL would have hit our bid → we buy at our bid
      const wouldBeInv = s.inventory + p.quoteSize;
      if (wouldBeInv <= p.invCap) {
        const fillSize = Math.min(p.quoteSize, trade.s);
        fill = { side: "B", price: bid, size: fillSize, ts: trade.ts, mid };
        s.inventory += fillSize;
        s.cash -= bid * fillSize;
        s.spreadPnL += (mid - bid) * fillSize;
        s.fillsBuy++;
        s.volTraded += fillSize;
      }
    }

    if (fill) {
      s.fills.push(fill);
      if (s.fills.length > FILLS_MAX) s.fills.shift();
      // Track for tox evaluation: we'll look at mid drift after TOX_LOOKAHEAD trades
      s.pendingFills.push({
        idxAtFill: s.index,
        side: fill.side,
        midAtFill: mid,
        priceAtFill: fill.price,
      });
    }

    // Evaluate ripe pending fills (tox detector)
    while (s.pendingFills.length > 0 && s.index - s.pendingFills[0].idxAtFill >= TOX_LOOKAHEAD) {
      const pf = s.pendingFills.shift();
      // Adverse drift: positive = mid moved against us
      // SELL (offer hit): adverse if mid went UP after we sold
      // BUY  (bid hit):   adverse if mid went DOWN after we bought
      const drift = pf.side === "S" ? (mid - pf.midAtFill) : -(mid - pf.midAtFill);
      s.closedEvals.push(drift);
      if (s.closedEvals.length > 60) s.closedEvals.shift();
    }

    // Sample inventory series (every 30 trades for sparkline)
    if (s.index % 30 === 0) {
      s.invSeries.push({ idx: s.index, ts: trade.ts, inv: s.inventory });
      if (s.invSeries.length > 200) s.invSeries.shift();
    }

    // Snapshot for chart (every 15th trade or on fill)
    if (s.index % 15 === 0 || fill) {
      const totalPnL = s.cash + s.inventory * mid;
      s.history.push({
        idx: s.index,
        ts: trade.ts,
        mid: +mid.toFixed(4),
        bid: +bid.toFixed(4),
        offer: +offer.toFixed(4),
        last: trade.p,
        side: trade.d,
        inventory: s.inventory,
        spreadPnL: +s.spreadPnL.toFixed(2),
        totalPnL: +totalPnL.toFixed(2),
        fillBuyPrice: fill && fill.side === "B" ? +fill.price.toFixed(4) : null,
        fillSellPrice: fill && fill.side === "S" ? +fill.price.toFixed(4) : null,
      });
      if (s.history.length > HISTORY_MAX * 2) {
        s.history = s.history.slice(-HISTORY_MAX);
      }
    }

    s.lastQuote = { mid, bid, offer };
    s.index++;
  };

  // ---- Replay loop ----
  useEffect(() => {
    if (!isPlaying) return;

    const id = setInterval(() => {
      const s = sim.current;
      const p = perillas.current;
      const tradesPerTick = Math.max(1, Math.round(speed * (TICK_MS / 1000)));

      for (let i = 0; i < tradesPerTick; i++) {
        if (s.index >= TRADES.length) {
          setIsPlaying(false);
          break;
        }
        processTrade(TRADES[s.index], p);
      }

      const trade = TRADES[Math.min(s.index, TRADES.length - 1)];
      const totalPnL = s.cash + s.inventory * s.lastQuote.mid;

      // Tox score: mean of last K closed evals normalized by half-spread
      const recentEvals = s.closedEvals.slice(-20);
      const meanDrift = recentEvals.length > 0
        ? recentEvals.reduce((a, b) => a + b, 0) / recentEvals.length
        : 0;
      const halfSpread = Math.max(p.spread / 2, 0.001);
      const toxScore = meanDrift / halfSpread;

      setDisplay({
        index: s.index,
        ts: trade?.ts ?? "—",
        mid: s.lastQuote.mid,
        bid: s.lastQuote.bid,
        offer: s.lastQuote.offer,
        inventory: s.inventory,
        spreadPnL: s.spreadPnL,
        invPnL: totalPnL - s.spreadPnL,
        totalPnL,
        fillsBuy: s.fillsBuy,
        fillsSell: s.fillsSell,
        volTraded: s.volTraded,
        fills: s.fills.slice(-12),
        history: s.history.slice(-HISTORY_MAX),
        invSeries: s.invSeries.slice(-150),
        toxScore,
        toxEvalsCount: s.closedEvals.length,
      });
    }, TICK_MS);

    return () => clearInterval(id);
  }, [isPlaying, speed]);

  // ---- Derived display values ----
  const progress = (display.index / TRADES.length) * 100;
  const invPctOfCap = invCap > 0 ? (display.inventory / invCap) * 100 : 0;
  const totalFills = display.fillsBuy + display.fillsSell;
  const hitRatio = totalFills > 0 ? display.fillsBuy / totalFills : 0.5;
  const isLong = display.inventory > 0;
  const isShort = display.inventory < 0;

  // ---- Convert UTC ts to AR time for display ----
  const arTime = (utcTs) => {
    if (!utcTs || utcTs === "—") return "—";
    const [h, m, s] = utcTs.split(":").map(Number);
    const arH = (h - 3 + 24) % 24;
    return `${String(arH).padStart(2, "0")}:${String(m).padStart(2, "0")}:${String(s).padStart(2, "0")}`;
  };

  return (
    <div style={styles.root}>
      <style>{globalCSS}</style>

      {/* ============================== HEADER ============================== */}
      <div style={styles.header}>
        <div style={styles.headerLeft}>
          <div style={styles.brand}>
            <span style={styles.brandDot}>●</span>
            MM WORKSTATION
          </div>
          <div style={styles.brandSub}>
            inventory · skew · pnl attribution — replay engine
          </div>
        </div>
        <div style={styles.headerRight}>
          <div style={styles.metaItem}>
            <span style={styles.metaLabel}>INSTRUMENTO</span>
            <span style={styles.metaVal}>{SESSION_INFO.ticker}</span>
          </div>
          <div style={styles.metaItem}>
            <span style={styles.metaLabel}>FECHA</span>
            <span style={styles.metaVal}>{SESSION_INFO.date}</span>
          </div>
          <div style={styles.metaItem}>
            <span style={styles.metaLabel}>SESSION CLOCK (AR)</span>
            <span style={{ ...styles.metaVal, color: "#ff9a3c" }}>{arTime(display.ts)}</span>
          </div>
        </div>
      </div>

      {/* ============================== INFO BAR ============================== */}
      <div style={styles.infoBar}>
        <InfoStat label="OPEN" value={fmtPrice(SESSION_INFO.open)} />
        <InfoStat label="HIGH" value={fmtPrice(SESSION_INFO.high)} />
        <InfoStat label="LOW" value={fmtPrice(SESSION_INFO.low)} />
        <InfoStat label="CLOSE" value={fmtPrice(SESSION_INFO.close)} />
        <InfoStat label="VOL DÍA" value={fmtVN(SESSION_INFO.total_vn)} />
        <InfoStat label="DUR" value={SESSION_INFO.duration} />
        <InfoStat label="TEA" value={(SESSION_INFO.tea * 100).toFixed(2) + "%"} />
        <div style={{ flex: 1 }} />
        <InfoStat label="TRADES VISTOS" value={`${display.index}/${TRADES.length}`} />
      </div>

      {/* ============================== CONTROLS ============================== */}
      <div style={styles.controlBar}>
        <button
          style={{ ...styles.btn, ...(isPlaying ? styles.btnActive : {}) }}
          onClick={() => setIsPlaying(p => !p)}
        >
          {isPlaying ? <Pause size={14} /> : <Play size={14} />}
          {isPlaying ? "PAUSE" : "PLAY"}
        </button>

        <button style={styles.btn} onClick={reset}>
          <RotateCcw size={14} />
          RESET
        </button>

        <div style={styles.speedGroup}>
          <span style={styles.speedLabel}>SPEED</span>
          {SPEEDS.map(s => (
            <button
              key={s.v}
              style={{
                ...styles.speedBtn,
                ...(speed === s.v ? styles.speedBtnActive : {})
              }}
              onClick={() => setSpeed(s.v)}
            >
              {s.label}
            </button>
          ))}
        </div>

        <div style={styles.progressContainer}>
          <div style={styles.progressBar}>
            <div style={{ ...styles.progressFill, width: `${progress}%` }} />
          </div>
          <span style={styles.progressLabel}>{progress.toFixed(1)}%</span>
        </div>

        <button
          style={{ ...styles.btn, ...styles.btnSweep, ...(sweepRunning ? styles.btnDisabled : {}) }}
          onClick={runSweep}
          disabled={sweepRunning}
          title="Corre el día completo a 12 spreads distintos manteniendo las otras perillas"
        >
          <Activity size={14} />
          {sweepRunning ? "RUNNING..." : "FIND SWEET SPOT"}
        </button>
      </div>

      {/* ============================== MAIN GRID ============================== */}
      <div style={styles.mainGrid}>
        {/* CHART (left, big) */}
        <div style={styles.chartPanel}>
          <div style={styles.panelHeader}>
            <span>PRICE STREAM — mid (smoothed) · your bid / offer · fills</span>
            <span style={styles.panelHeaderRight}>
              <Legend dot="#ff9a3c" label="MID" />
              <Legend dot="#3ce5a5" label="BID" />
              <Legend dot="#ff5d6c" label="OFFER" />
              <Legend dot="#fff" label="FILL" />
            </span>
          </div>
          <PriceChart history={display.history} />
        </div>

        {/* RIGHT COLUMN: Quote + Inv + PnL stacked */}
        <div style={styles.rightCol}>
          <QuoteBox
            mid={display.mid}
            bid={display.bid}
            offer={display.offer}
            quoteSize={quoteSize}
            skewActive={autoSkew && Math.abs(display.inventory) > 0}
          />
          <InventoryBox
            inv={display.inventory}
            invCap={invCap}
            pct={invPctOfCap}
            isLong={isLong}
            isShort={isShort}
            duration={SESSION_INFO.duration}
            mid={display.mid}
          />
          <PnLBox
            total={display.totalPnL}
            spread={display.spreadPnL}
            inv={display.invPnL}
            fillsBuy={display.fillsBuy}
            fillsSell={display.fillsSell}
            volTraded={display.volTraded}
          />
        </div>
      </div>

      {/* ============================== TOX + INV STRIP ============================== */}
      <div style={styles.diagStrip}>
        <ToxPanel score={display.toxScore} count={display.toxEvalsCount} />
        <InvSparkline series={display.invSeries} cap={invCap} />
      </div>

      {/* ============================== SWEEP RESULTS ============================== */}
      {sweepResults && (
        <SweepResultsPanel
          results={sweepResults}
          currentSpread={spread}
          onClose={() => setSweepResults(null)}
          onPickSpread={(s) => setSpread(s)}
        />
      )}

      {/* ============================== PERILLAS ============================== */}
      <div style={styles.perillasPanel}>
        <div style={styles.panelHeader}>
          <span>PERILLAS DEL MOTOR — ajustá en vivo durante el replay</span>
        </div>
        <div style={styles.perillasGrid}>
          <Perilla
            label="SPREAD"
            value={spread}
            min={0.02}
            max={0.40}
            step={0.01}
            onChange={setSpread}
            display={`${(spread * 100).toFixed(0)}c  ≈  ${(spread / display.mid * 10000).toFixed(0)}bps`}
            help="Distancia bid↔offer. Más ancho = menos fills, más edge por fill."
          />
          <Perilla
            label="TAMAÑO"
            value={quoteSize}
            min={1000}
            max={100000}
            step={1000}
            onChange={setQuoteSize}
            display={`${fmtVN(quoteSize)} VN/lado`}
            help="Cuánto VN ofrecés visible por lado. Más tamaño = más fills + más riesgo de inventory."
          />
          <Perilla
            label="SKEW INTENSITY"
            value={skewIntensity}
            min={0}
            max={3}
            step={0.1}
            onChange={setSkewIntensity}
            display={`${skewIntensity.toFixed(1)}x`}
            help="Cuánto desplaza tus precios el inventory. 0=off, 1=normal, 3=agresivo."
            disabled={!autoSkew}
          />
          <Perilla
            label="INV CAP"
            value={invCap}
            min={20000}
            max={500000}
            step={10000}
            onChange={setInvCap}
            display={`±${fmtVN(invCap)} VN`}
            help="Límite duro de inventario. Cuando se alcanza, ese lado deja de fillear."
          />
        </div>
        <div style={styles.toggleRow}>
          <label style={styles.toggleLbl}>
            <input
              type="checkbox"
              checked={autoSkew}
              onChange={e => setAutoSkew(e.target.checked)}
              style={styles.checkbox}
            />
            <span>AUTO-SKEW</span>
            <span style={styles.toggleHelp}>
              Cuando está ON, el sistema mueve tus quotes según inventory para descargar.
            </span>
          </label>
        </div>
      </div>

      {/* ============================== FILLS TAPE ============================== */}
      <div style={styles.fillsPanel}>
        <div style={styles.panelHeader}>
          <span>RECENT FILLS — últimos {display.fills.length}</span>
          <span style={styles.panelHeaderRight}>
            <span style={{ color: "#3ce5a5" }}>BUYS: {display.fillsBuy}</span>
            <span style={{ color: "#888", margin: "0 8px" }}>·</span>
            <span style={{ color: "#ff5d6c" }}>SELLS: {display.fillsSell}</span>
            <span style={{ color: "#888", margin: "0 8px" }}>·</span>
            <span>HIT RATIO: {(hitRatio * 100).toFixed(0)}% B</span>
          </span>
        </div>
        <FillsTape fills={display.fills} arTime={arTime} />
      </div>

      {/* ============================== FOOTER ============================== */}
      <div style={styles.footer}>
        <span style={styles.footerItem}>data: ACAQUANT MCP · TimeSales AL30D · 28-abr-2026</span>
        <span style={{ flex: 1 }} />
        <span style={styles.footerItem}>{display.index >= TRADES.length ? "● SESSION CLOSED" : (isPlaying ? "● LIVE REPLAY" : "○ PAUSED")}</span>
      </div>
    </div>
  );
}

// ============================================================
// SUB-COMPONENTS
// ============================================================

function InfoStat({ label, value }) {
  return (
    <div style={styles.infoStat}>
      <span style={styles.infoLabel}>{label}</span>
      <span style={styles.infoVal}>{value}</span>
    </div>
  );
}

function Legend({ dot, label }) {
  return (
    <span style={styles.legend}>
      <span style={{ ...styles.legendDot, background: dot }}></span>
      {label}
    </span>
  );
}

// -------- Price Chart --------
function PriceChart({ history }) {
  if (!history || history.length === 0) {
    return (
      <div style={styles.chartEmpty}>
        Apretá PLAY para arrancar el replay.<br/>
        <span style={{ fontSize: 11, opacity: 0.5 }}>El sistema procesa cada trade real del día y lo cruza contra tus cotizaciones simuladas.</span>
      </div>
    );
  }

  // Compute Y bounds with padding
  const allVals = history.flatMap(h => [h.mid, h.bid, h.offer, h.last]);
  const yMin = Math.min(...allVals) - 0.02;
  const yMax = Math.max(...allVals) + 0.02;

  return (
    <div style={{ width: "100%", height: 280 }}>
      <ResponsiveContainer>
        <ComposedChart data={history} margin={{ top: 10, right: 12, left: -8, bottom: 4 }}>
          <XAxis
            dataKey="ts"
            tick={{ fill: "#666", fontSize: 9, fontFamily: "JetBrains Mono, monospace" }}
            stroke="#222"
            interval="preserveStartEnd"
            minTickGap={60}
          />
          <YAxis
            domain={[yMin, yMax]}
            tick={{ fill: "#666", fontSize: 10, fontFamily: "JetBrains Mono, monospace" }}
            stroke="#222"
            tickFormatter={v => v.toFixed(2)}
            width={50}
          />
          <Tooltip
            contentStyle={{
              background: "#0d0d0d",
              border: "1px solid #2a2a2a",
              fontSize: 11,
              fontFamily: "JetBrains Mono, monospace",
              borderRadius: 0,
            }}
            labelStyle={{ color: "#ff9a3c" }}
            formatter={(v, name) => [typeof v === "number" ? v.toFixed(3) : v, name]}
          />

          <Line
            type="monotone"
            dataKey="bid"
            stroke="#3ce5a5"
            strokeWidth={1}
            dot={false}
            isAnimationActive={false}
            strokeDasharray="3 3"
            opacity={0.7}
            connectNulls
          />
          <Line
            type="monotone"
            dataKey="offer"
            stroke="#ff5d6c"
            strokeWidth={1}
            dot={false}
            isAnimationActive={false}
            strokeDasharray="3 3"
            opacity={0.7}
            connectNulls
          />
          <Line
            type="monotone"
            dataKey="mid"
            stroke="#ff9a3c"
            strokeWidth={1.6}
            dot={false}
            isAnimationActive={false}
            connectNulls
          />

          {/* Fill markers — dot-only lines (null elsewhere = no dot rendered) */}
          <Line
            dataKey="fillBuyPrice"
            stroke="none"
            isAnimationActive={false}
            dot={{ r: 4, fill: "#3ce5a5", stroke: "#0a0a0a", strokeWidth: 1.5 }}
            activeDot={false}
          />
          <Line
            dataKey="fillSellPrice"
            stroke="none"
            isAnimationActive={false}
            dot={{ r: 4, fill: "#ff5d6c", stroke: "#0a0a0a", strokeWidth: 1.5 }}
            activeDot={false}
          />
        </ComposedChart>
      </ResponsiveContainer>
    </div>
  );
}

