// -------- Inventory Box --------
function InventoryBox({ inv, invCap, pct, isLong, isShort, duration, mid }) {
  const color = isLong ? "#3ce5a5" : isShort ? "#ff5d6c" : "#888";
  const pctAbs = Math.abs(pct);
  const dv01 = (inv * mid * duration / 10000); // approx DV01 in USD per bp

  return (
    <div style={styles.subPanel}>
      <div style={styles.subPanelHeader}>
        <span>INVENTORY</span>
        {isLong && <span style={{ ...styles.invBadge, background: "rgba(60,229,165,0.15)", color: "#3ce5a5" }}>LONG</span>}
        {isShort && <span style={{ ...styles.invBadge, background: "rgba(255,93,108,0.15)", color: "#ff5d6c" }}>SHORT</span>}
        {!isLong && !isShort && <span style={{ ...styles.invBadge, background: "rgba(136,136,136,0.15)", color: "#888" }}>FLAT</span>}
      </div>
      <div style={styles.invMain}>
        <div style={{ ...styles.invValue, color }}>
          {inv === 0 ? "0" : (inv > 0 ? "+" : "") + fmtVN(inv)}
        </div>
        <div style={styles.invSubLabel}>VN nominales · cap ±{fmtVN(invCap)}</div>
      </div>
      <div style={styles.invBarContainer}>
        <div style={styles.invBarTrack}>
          <div style={styles.invBarMid}></div>
          <div
            style={{
              ...styles.invBarFill,
              width: `${Math.min(pctAbs, 100) / 2}%`,
              background: color,
              left: pct >= 0 ? "50%" : `${50 - Math.min(pctAbs, 100) / 2}%`,
            }}
          />
        </div>
        <div style={styles.invBarLabels}>
          <span>-{fmtVN(invCap)}</span>
          <span>0</span>
          <span>+{fmtVN(invCap)}</span>
        </div>
      </div>
      <div style={styles.invStats}>
        <div style={styles.invStatRow}>
          <span style={styles.invStatLbl}>% del cap</span>
          <span style={{ ...styles.invStatVal, color }}>{pct.toFixed(1)}%</span>
        </div>
        <div style={styles.invStatRow}>
          <span style={styles.invStatLbl}>DV01 aprox</span>
          <span style={styles.invStatVal}>${fmtNum(Math.abs(dv01), 2)}</span>
        </div>
      </div>
    </div>
  );
}

// -------- PnL Box --------
function PnLBox({ total, spread, inv, fillsBuy, fillsSell, volTraded }) {
  const totalColor = total > 1 ? "#3ce5a5" : total < -1 ? "#ff5d6c" : "#aaa";
  const invColor = inv > 1 ? "#3ce5a5" : inv < -1 ? "#ff5d6c" : "#888";
  const totalFills = fillsBuy + fillsSell;

  return (
    <div style={styles.subPanel}>
      <div style={styles.subPanelHeader}>
        <span>PNL · ATTRIBUTION</span>
      </div>
      <div style={styles.pnlMain}>
        <div style={styles.pnlMainLabel}>TOTAL</div>
        <div style={{ ...styles.pnlMainValue, color: totalColor }}>
          ${fmtUSD(total)}
        </div>
      </div>
      <div style={styles.pnlBreakdown}>
        <div style={styles.pnlRow}>
          <span style={styles.pnlRowLbl}>SPREAD CAPTURED</span>
          <span style={{ ...styles.pnlRowVal, color: "#3ce5a5" }}>
            +{fmtNum(spread, 0)}
          </span>
        </div>
        <div style={styles.pnlRow}>
          <span style={styles.pnlRowLbl}>INVENTORY MTM</span>
          <span style={{ ...styles.pnlRowVal, color: invColor }}>
            {inv >= 0 ? "+" : ""}{fmtNum(inv, 0)}
          </span>
        </div>
        <div style={{ ...styles.pnlRow, borderTop: "1px dashed #2a2a2a", paddingTop: 6 }}>
          <span style={styles.pnlRowLbl}>FILLS</span>
          <span style={styles.pnlRowVal}>
            {totalFills}
          </span>
        </div>
        <div style={styles.pnlRow}>
          <span style={styles.pnlRowLbl}>VOL TRADED</span>
          <span style={styles.pnlRowVal}>
            {fmtVN(volTraded)}
          </span>
        </div>
      </div>
    </div>
  );
}

// -------- Perilla --------
function Perilla({ label, value, min, max, step, onChange, display, help, disabled }) {
  return (
    <div style={{ ...styles.perilla, opacity: disabled ? 0.4 : 1 }}>
      <div style={styles.perillaHead}>
        <span style={styles.perillaLabel}>{label}</span>
        <span style={styles.perillaValue}>{display}</span>
      </div>
      <input
        type="range"
        min={min}
        max={max}
        step={step}
        value={value}
        onChange={e => onChange(parseFloat(e.target.value))}
        disabled={disabled}
        style={styles.slider}
      />
      <div style={styles.perillaHelp}>{help}</div>
    </div>
  );
}

// -------- Fills Tape --------
function FillsTape({ fills, arTime }) {
  if (!fills || fills.length === 0) {
    return <div style={styles.fillsEmpty}>Aún no hubo fills.</div>;
  }

  // Show newest first
  const reversed = [...fills].reverse();

  return (
    <div style={styles.fillsList}>
      <div style={styles.fillsHeader}>
        <span style={{ width: 80 }}>HORA AR</span>
        <span style={{ width: 60 }}>SIDE</span>
        <span style={{ width: 80, textAlign: "right" }}>PRICE</span>
        <span style={{ width: 80, textAlign: "right" }}>SIZE VN</span>
        <span style={{ width: 80, textAlign: "right" }}>EDGE</span>
        <span style={{ width: 100, textAlign: "right" }}>USD</span>
      </div>
      {reversed.map((f, i) => {
        const isBuy = f.side === "B";
        const sideColor = isBuy ? "#3ce5a5" : "#ff5d6c";
        const edge = isBuy ? f.mid - f.price : f.price - f.mid;
        const usd = f.price * f.size;
        return (
          <div key={`fill-${i}-${f.ts}-${f.size}`} style={styles.fillsRow}>
            <span style={{ width: 80, color: "#666" }}>{arTime(f.ts)}</span>
            <span style={{ width: 60, color: sideColor, fontWeight: 600 }}>
              {isBuy ? "BUY" : "SELL"}
            </span>
            <span style={{ width: 80, textAlign: "right", color: "#fff" }}>
              {fmtPrice(f.price)}
            </span>
            <span style={{ width: 80, textAlign: "right", color: "#aaa" }}>
              {fmtVN(f.size)}
            </span>
            <span style={{ width: 80, textAlign: "right", color: "#3ce5a5" }}>
              +{fmtNum(edge * 1000, 1)}m¢
            </span>
            <span style={{ width: 100, textAlign: "right", color: "#aaa" }}>
              ${fmtNum(usd, 0)}
            </span>
          </div>
        );
      })}
    </div>
  );
}

// -------- Tox Detector Panel --------
function ToxPanel({ score, count }) {
  // Score interpretation:
  // < 0       → favorable flow (we picked good fills)
  // 0 to 0.5  → neutral
  // 0.5 to 1  → atención
  // > 1       → toxic
  let label, color, action;
  if (count < 5) {
    label = "WARMING UP";
    color = "#888";
    action = `${count}/5 evaluaciones para arrancar`;
  } else if (score < -0.1) {
    label = "BUEN FLOW";
    color = "#3ce5a5";
    action = "estás picking good flow — el mid se mueve a tu favor post-fill";
  } else if (score < 0.4) {
    label = "NEUTRAL";
    color = "#aaa";
    action = "flow zero-mean. Nada raro.";
  } else if (score < 1.0) {
    label = "ATENCIÓN";
    color = "#ff9a3c";
    action = "el mid se mueve en contra después de tus fills. Empezá a ensanchar spread.";
  } else {
    label = "TÓXICO";
    color = "#ff5d6c";
    action = "adverse selection severo — alguien te está cazando. Subí spread o pausá.";
  }

  // Position on the bar: clamp -1.5 to 2.5
  const clamped = Math.max(-1.5, Math.min(2.5, score));
  const pctPos = ((clamped + 1.5) / 4.0) * 100;

  return (
    <div style={styles.toxPanel}>
      <div style={styles.toxHeader}>
        <span style={styles.toxTitle}>
          <Activity size={11} style={{ marginRight: 6, verticalAlign: "middle" }} />
          TOX FLOW DETECTOR
        </span>
        <span style={{ ...styles.toxLabel, color, borderColor: color }}>{label}</span>
      </div>
      <div style={styles.toxBarOuter}>
        <div style={styles.toxBarTrack}>
          <div style={{ ...styles.toxThresholdMark, left: "37.5%" }} />
          <div style={{ ...styles.toxThresholdMark, left: "47.5%" }} />
          <div style={{ ...styles.toxThresholdMark, left: "62.5%" }} />
          <div style={{
            ...styles.toxIndicator,
            left: `calc(${pctPos}% - 1px)`,
            background: color,
          }} />
        </div>
        <div style={styles.toxBarLabels}>
          <span>FAVOR</span>
          <span>NEUTRAL</span>
          <span>WATCH</span>
          <span>TOX</span>
        </div>
      </div>
      <div style={styles.toxStatRow}>
        <span style={styles.toxStatLbl}>SCORE</span>
        <span style={{ ...styles.toxStatVal, color }}>{score.toFixed(2)}σ</span>
        <span style={{ ...styles.toxStatLbl, marginLeft: 16 }}>EVALS</span>
        <span style={styles.toxStatVal}>{count}</span>
      </div>
      <div style={styles.toxAction}>{action}</div>
    </div>
  );
}

// -------- Inventory Sparkline --------
function InvSparkline({ series, cap }) {
  if (!series || series.length < 2) {
    return (
      <div style={styles.sparkPanel}>
        <div style={styles.sparkHeader}>INVENTORY OVER SESSION</div>
        <div style={styles.sparkEmpty}>El sparkline se va a llenar mientras corre el replay.</div>
      </div>
    );
  }

  return (
    <div style={styles.sparkPanel}>
      <div style={styles.sparkHeader}>
        <span>INVENTORY OVER SESSION — cap ±{fmtVN(cap)}</span>
        <span style={styles.sparkRange}>{series.length} pts · 30-trade resolution</span>
      </div>
      <div style={{ width: "100%", height: 90 }}>
        <ResponsiveContainer>
          <ComposedChart data={series} margin={{ top: 4, right: 4, left: -10, bottom: 0 }}>
            <XAxis dataKey="ts" hide />
            <YAxis
              domain={[-cap, cap]}
              tick={{ fill: "#555", fontSize: 9, fontFamily: "IBM Plex Mono, monospace" }}
              stroke="#222"
              tickFormatter={v => fmtVN(v)}
              width={48}
            />
            <Line
              type="monotone"
              dataKey="inv"
              stroke="#ff9a3c"
              strokeWidth={1.4}
              dot={false}
              isAnimationActive={false}
            />
          </ComposedChart>
        </ResponsiveContainer>
      </div>
    </div>
  );
}

// -------- Sweep Results Panel --------
function SweepResultsPanel({ results, currentSpread, onClose, onPickSpread }) {
  // Find best
  const best = [...results].sort((a, b) => b.totalPnL - a.totalPnL)[0];

  return (
    <div style={styles.sweepPanel}>
      <div style={styles.sweepHeader}>
        <span style={styles.sweepTitle}>
          <Activity size={12} style={{ marginRight: 6, verticalAlign: "middle" }} />
          SPREAD SWEEP — {results.length} corridas del día completo · sweet spot:
          <span style={{ color: "#3ce5a5", marginLeft: 6 }}>
            {(best.spread * 100).toFixed(0)}c (PnL ${fmtUSD(best.totalPnL)})
          </span>
        </span>
        <button onClick={onClose} style={styles.sweepClose}>×</button>
      </div>

      <div style={styles.sweepBody}>
        {/* Chart */}
        <div style={{ flex: 1, minWidth: 0, height: 220 }}>
          <ResponsiveContainer>
            <ComposedChart data={results} margin={{ top: 8, right: 12, left: 0, bottom: 20 }}>
              <XAxis
                dataKey="spread"
                type="number"
                domain={["dataMin", "dataMax"]}
                tick={{ fill: "#888", fontSize: 10, fontFamily: "IBM Plex Mono, monospace" }}
                stroke="#222"
                tickFormatter={v => (v * 100).toFixed(0) + "c"}
                label={{ value: "SPREAD", position: "insideBottom", offset: -10, fill: "#666", fontSize: 9 }}
              />
              <YAxis
                yAxisId="pnl"
                tick={{ fill: "#888", fontSize: 10, fontFamily: "IBM Plex Mono, monospace" }}
                stroke="#222"
                tickFormatter={v => "$" + (v / 1000).toFixed(0) + "k"}
                width={50}
              />
              <Tooltip
                contentStyle={{
                  background: "#0d0d0d",
                  border: "1px solid #2a2a2a",
                  fontSize: 11,
                  fontFamily: "IBM Plex Mono, monospace",
                  borderRadius: 0,
                }}
                labelFormatter={v => `Spread ${(v * 100).toFixed(0)}c`}
                formatter={(v, name) => {
                  if (name === "totalPnL") return [`$${fmtUSD(v)}`, "Total PnL"];
                  if (name === "spreadPnL") return [`$${fmtUSD(v)}`, "Spread Captured"];
                  if (name === "invPnL") return [`$${fmtUSD(v)}`, "Inventory MTM"];
                  return [v, name];
                }}
              />
              <Line yAxisId="pnl" type="monotone" dataKey="spreadPnL" stroke="#3ce5a5" strokeWidth={1.2} strokeDasharray="3 3" dot={{ r: 2 }} isAnimationActive={false} />
              <Line yAxisId="pnl" type="monotone" dataKey="invPnL" stroke="#ff5d6c" strokeWidth={1.2} strokeDasharray="3 3" dot={{ r: 2 }} isAnimationActive={false} />
              <Line yAxisId="pnl" type="monotone" dataKey="totalPnL" stroke="#ff9a3c" strokeWidth={2} dot={{ r: 3 }} isAnimationActive={false} />
            </ComposedChart>
          </ResponsiveContainer>
        </div>

        {/* Table */}
        <div style={styles.sweepTable}>
          <div style={styles.sweepTableHeader}>
            <span style={{ width: 50 }}>SPREAD</span>
            <span style={{ width: 70, textAlign: "right" }}>TOTAL</span>
            <span style={{ width: 60, textAlign: "right" }}>SPREAD$</span>
            <span style={{ width: 60, textAlign: "right" }}>INV MTM</span>
            <span style={{ width: 50, textAlign: "right" }}>FILLS</span>
            <span style={{ width: 30 }}></span>
          </div>
          {results.map(r => {
            const isBest = r.spread === best.spread;
            const isCurrent = Math.abs(r.spread - currentSpread) < 0.001;
            return (
              <div
                key={r.spread}
                style={{
                  ...styles.sweepRow,
                  ...(isBest ? styles.sweepRowBest : {}),
                  ...(isCurrent ? styles.sweepRowCurrent : {}),
                }}
              >
                <span style={{ width: 50, color: isBest ? "#3ce5a5" : "#fff" }}>
                  {(r.spread * 100).toFixed(0)}c
                </span>
                <span style={{
                  width: 70, textAlign: "right",
                  color: r.totalPnL > 0 ? "#3ce5a5" : "#ff5d6c",
                  fontWeight: 500,
                }}>
                  ${fmtUSD(r.totalPnL)}
                </span>
                <span style={{ width: 60, textAlign: "right", color: "#888" }}>
                  ${fmtNum(r.spreadPnL, 0)}
                </span>
                <span style={{
                  width: 60, textAlign: "right",
                  color: r.invPnL >= 0 ? "#3ce5a5" : "#ff5d6c",
                }}>
                  {r.invPnL >= 0 ? "+" : ""}{fmtNum(r.invPnL, 0)}
                </span>
                <span style={{ width: 50, textAlign: "right", color: "#888" }}>
                  {r.totalFills}
                </span>
                <button
                  style={styles.sweepPickBtn}
                  onClick={() => onPickSpread(r.spread)}
                  title="Aplicar este spread"
                >→</button>
              </div>
            );
          })}
        </div>
      </div>

      <div style={styles.sweepFooter}>
        <span style={styles.sweepLegend}>
          <span style={{ ...styles.legendDot, background: "#ff9a3c", width: 10 }}></span> TOTAL PnL
        </span>
        <span style={styles.sweepLegend}>
          <span style={{ ...styles.legendDot, background: "#3ce5a5", width: 10 }}></span> Spread Captured
        </span>
        <span style={styles.sweepLegend}>
          <span style={{ ...styles.legendDot, background: "#ff5d6c", width: 10 }}></span> Inventory MTM
        </span>
        <span style={{ flex: 1 }} />
        <span style={{ color: "#666", fontSize: 9 }}>
          Asume las otras perillas (tamaño, skew, cap) constantes en sus valores actuales.
        </span>
      </div>
    </div>
  );
}

